int MaximumValue(int l, int r){
        int max_value = 0;
        int result = 0;


        for(int i = l ; i<=r ;i++){
            for(int j = i ; j<=r ;j++){
                result = i^j;
                if(result > max_value){
                    max_value = result;
                }
            }
        }
        return max_value;
}

