int * Swap(int a_size,int *a,int b_size,int *b)
{
    int temp;
    int i;
    for(i=0;i<b_size;i++)
    {
        temp = a[i];
        a[i] = b[i];
        b[i] = temp;
    }
    return a;
}


int main(void)
