    printf("Podaj liczby rzeczywsite, po wpisaniu 0 program zakonczy wczytywanie.\nLiczby:\n");
    scanf("%Lf", &kolejna);

    suma += kolejna;


    if (kolejna != 0)
    {
        int i = 1;
        min = kolejna;
        max = kolejna;
        scanf("%Lf", &kolejna);
        suma += kolejna;
        srednia = suma / i++;
        while (kolejna)
        {
            if (kolejna > max)
                max = kolejna;
            else {
                if (kolejna < min)
                    min = kolejna;
            }
            scanf("%Lf", &kolejna);
            suma += kolejna;
            srednia = suma / i++;
