    int **mat ;
    mat = (int**)malloc(m*sizeof(int*));
    for(int i = 0 ; i < m ; i++)
    {
        mat[i] = (int*)malloc(n*sizeof(int));
    }
    for(int i = 0 ; i < m ; i++)
    {
        for(int j = 0 ; j < n ; j++)
        {
            printf("Enter element at row %d, column %d : ", i, j);
            scanf("%d", &mat[i][j]);
        }
