    printf("Before sorting : \n");
    for(int i = 0 ; i < m ; i++)
    {
        for (int j = 0 ; j < n ; j++)
        {
            printf("%d ", mat[i][j]);
        }
        printf("\n");
    }
    rowsort(mat, m ,n);
    printf("After Sorting Rows : \n");
