void ngerearrange( int *arr, int n)
{
    int i, j;
    for (i=0; i<n; i++)
    {
        for (j = i+1; j<n; j++)
        {
            if (*(arr + i) < *(arr + j))
            {
                *(arr + i) = *(arr + j);
                break;
            }
        }
    }
}

