void printPoly(int poly[], int n)
{
    for (int i = 0 ; i < n ; i++)
    {
        printf("%d", poly[i]);
        if (i != 0)
            printf("x^%d", i) ;
        if (i != n-1)
            printf(" + ");
    }
    printf("\n");
}

int *multiply(int A[], int B[], int n, int m)
{
    int *prod = (int*)malloc((n + m - 1)*sizeof(int));

    for (int i = 0; i < n + m - 1; i++)
        prod[i] = 0;


    for (int i = 0 ; i < n; i++)
    {
        for (int j = 0 ; j < m ; j++)
            prod[i+j] += A[i]*B[j];
    }

    printPoly(prod, n+m-1);
    return prod;
}

