int *add(int A[], int B[], int n, int m)
{
    int max;
    if(m>n)
        max = m;
    else
        max = n;
    int *sum = (int*)malloc(max*sizeof(int));

    for (int i = 0; i<n; i++)
        sum[i] = A[i];

    for (int i=0; i<m; i++)
        sum[i] += B[i];

    printPoly(sum, max);
    return sum;
}

