char *_itoa(unsigned int n)
{
    int len = 0, i = 0;
    char *s;

    len = intlen(n);
    s = malloc(len + 1);
    if (!s)
        return (NULL);
    *s = '\0';
    while (n / 10)
    {
        s[i] = (n % 10) + '0';
        n /= 10;
        i++;
    }
    s[i] = (n % 10) + '0';
    array_rev(s, len);
    s[i + 1] = '\0';
    return (s);
}

void array_rev(char *arr, int len)
{
    int i;
    char tmp;

    for (i = 0; i < (len / 2); i++)
    {
        tmp = arr[i];
        arr[i] = arr[(len - 1) - i];
        arr[(len - 1) - i] = tmp;
    }
}

int intlen(int num)
{
    int len = 0;

    while (num != 0)
    {
        len++;
        num /= 10;
    }
    return (len);
}
