int sum_of_num(int array[],int n)
{
    int sum=0;
    for(i=1;i<n;i++)
    {
        sum+=array[i];
    }
    return sum;
}



float average_of_num(int sum,int n)
{
    float average=0;
    average=sum/(n-1);
    return average;
}



float product_of_num(int array[],int n)
{
    float product=1;
    for(i=1;i<n;i++)
    {
        product*=array[i];
    }
    return product;
}
