    i = 0;
    while (s[i])
    {
        free(s[i]);
        i++;
    }
    free(s);
    return (NULL);
}

int     s_p(char *s, char c)
{
    int i;

    i = 0;
    while (s[i] == c && s[i])
        i++;
    return (i);
}

int     len_str(char *s, int i, char c)
{
    int len;

    len = 0;
    while (s[i] != c && s[i])
    {
        len++;
        i++;
    }
    return (len);
}

