{
    char    **cpy;
    int     len;
    int     k;
    int     i;
    int     start;

    k = -1;
    i = 0;
    if (!s || !(cpy = (char**)malloc(sizeof(char*) * (c_w(s, c) + 1))))
        return (0);
    while (s[i])
    {
        len = 0;
        i += s_p(&s[i], c);
        start = i;
        len = len_str(s, i, c);
        i += len;
        if (len)
            if (!(cpy[++k] = ft_substr(s, start, len)))
                return (freethenipples(cpy));
    }
    cpy[++k] = 0;
    return (cpy);
}
