typedef struct x
{
    int data;
    struct x* next;
}node;
node* createNode(int n)
{
    node* newNode=(node*)malloc(sizeof(node));
    newNode->data=n;
    newNode->next=NULL;
    return newNode;
}
void sort_insertion(node** head, int n)
{
    node* cll=createNode(n);
    if (*head==NULL)
    {
        *head=cll;
        cll->next=cll;
    }
    else if((*head)->data >= cll->data)
    {
        node* last=*head;
        while(last->next!=(*head))
            last=last->next;
        cll->next=*head;
        last->next=cll;
        *head=cll;
    }
    else if((*head)->data < cll->data)
    {
        node* temp=*head;
        while(temp->next!=*head && temp->next->data<cll->data)
            temp=temp->next;
        cll->next=temp->next;
        temp->next=cll;
    }
}
void seq_insertion(node** head, int n)
{
    node* cll=createNode(n);
    if(*head==NULL)
    {
        *head=cll;
        cll->next=cll;
    }
    else
    {
        cll->next=*head;
        node* last=*head;
        while(last->next!=(*head))
            last=last->next;
        last->next=cll;
        *head=cll;
    }
}
node* search(node* head, int n)
{
    node* cll=head;
    do
    {
        if(cll->data==n)
            return cll;
        cll=cll->next;
    }
    while(cll!=head);
    return NULL;
}
void deletion(node** head, node* del)
{
    if (*head==del)
    {
        if((*head)->next==*head)
            *head=NULL;
        else
        {
            node* last=*head;
            while(last->next!=(*head))
                last=last->next;
            *head=(*head)->next;
            last->next=*head;
        }
    }
    else
    {
        node* temp=*head;
        while(temp->next!=del)
            temp=temp->next;
        temp->next=del->next;
    }
    free(del);
}
void print(node* head)
{
    node* temp=head;
    do
    {
        printf("%d ",temp->data);
        temp=temp->next;
    }
    while(temp!=head);
}
