        printf("ERROR");
    else
    {
        static int c=0;
        if(n==1)
        {
            c++;
            printf("%d: Move top disk from %c to %c\n",c,src,dest);
            return;
        }
        move(n-1,src,inter,dest);
        c++;
        printf("%d: Move top disk from %c to %c\n",c,src,dest);
        move(n-1,inter,dest,src);
    }
}
