int SearchFirstOcc(char str[], char ch)
{
    int i = 0;

    if((str == NULL) || (ch == '\0'))
    {
        return -1;
    }

    while(str[i] != '\0')
    {
            if(str[i] == ch)
            {
                break;
            }
        i++;
    }

    if(str[i] == ch)        
    {
        return i;
    }
    else                        
    {
        return -1;
    }

}





