void selection_sort(int *array, size_t size)
{
    int min;
    size_t i;
    size_t j;
    size_t position;

    if (array == NULL)
        return;

    for (i = 0; i < size; i++)
    {
        min = array[i];
        position = i;

        for (j = i + 1; j < size; j++)
        {
            if (min > array[j])
            {
                position = j;
                min = array[j];
            }
        }
        if (position != i)
        {
            array[position] = array[i];
            array[i] = min;
            print_array(array, size);
        }
    }
}
