void selection_sort(int array[MAX], int length)
{
    int i, j, temp, pointer = 0;
    int size = length;

    for(i=0; i<size-1; i++)
    {

        pointer = i;
        for(j=i+1; j<size; j++)
        {

            if(array[pointer] > array[j])
            {

                pointer = j;
            }

            if(pointer != i)
            {

                temp = array[pointer];
                array[pointer] = array[i];
                array[i] = temp;
