int swap(int* a, int* b)
{
  int temp = *a;
  *a = *b;
  *b = temp;
}



int sort(int arr[], int size)
{
  int low,mid,high;
  low = mid = 0;
  high = (size-1);
  while(mid<=high)
  {
    switch (arr[mid]) 
    { 
      case 0: 
          swap(&arr[low++], &arr[mid++]); 
          break; 
      case 1: 
          mid++; 
          break; 
      case 2: 
          swap(&arr[mid], &arr[high--]); 
          break;
    }
  }
}





