void change(int vector[], int i, int j){
  int aux;

  aux = vector[i];
  vector[i] = vector[j];
  vector[j] = aux;
}


void quicksort(int vector[], int inf, int sup){
  int i, j, x;

  i = inf;
  j = sup;
  x = vector[(i+j)/2];

  while(i <= j){ 
