{
    if(r==-1)
    {
        f=(f+1)%MAX;
        r=(r+1)%MAX;
        queue[r]=val;
    }
    else if((r==MAX-1 && f==0) || r==f-1)
    {
        printf("\nQueue is FULL");
    }
    else
    {
        r=(r+1)%MAX;
        queue[r]=val;
    }
}
int dequeue()
{
    if((f==-1 && r==-1))
    {
        printf("\nQueue is Empty");
        return(-1);
    }
    else
    {
        if(f==(r+1)%MAX && queue[f]==-1)    
        {
            printf("\nQueue is Empty");
            return(-1);
        }
        else
        {
            value=queue[f];
            queue[f]=-1;
            f=(f+1)%MAX;
            return(value);
        }
    }
}
