typedef struct node* nptr;
typedef struct node
{
    int data;
    nptr next;
}node;

nptr createNode(int x)
{
    nptr temp = (nptr)malloc(sizeof(node));
    temp -> data = x;
    temp -> next = NULL;

    return temp;
}

void insert(nptr &head, int ele)
{
    if (head == NULL)
    {
        head = createNode(ele);
        return;
    }

    else if (ele < head -> data)
    {
        nptr temp = createNode(ele);
        temp -> next = head;
        head = temp;
        return;
    }

    else
    {
        nptr prev = NULL, curr = head;

