void reverse_node(struct node*head1, struct node*temp1)
{
    struct node*prevnode;
    if(head1!=NULL)
    {
        prevnode = head1;
        temp1 = head1->ptr;
        head1 = head1->ptr;
        prevnode->ptr = NULL;
    }
    while(head1!=NULL)
    {
        head1 = head1->ptr;
        temp1->ptr = prevnode;
        prevnode = temp1;
        temp1 = head1;
    }
    head1 = prevnode;
    printf("\nAFTER REVERSE OPERATION:");
    while(head1!=NULL)
    {
        printf("%d\t",head1->data);
        head1 = head1->ptr;
    }
    return;
